-- NutriTrack MBG - Skema & Data Asli
-- Import via phpMyAdmin / HeidiSQL (Laragon)
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS nutritrackmbg DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nutritrackmbg;

DROP TABLE IF EXISTS foods;
CREATE TABLE foods (
  id INT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  category VARCHAR(80),
  calories DECIMAL(8,2) DEFAULT 0,
  protein DECIMAL(8,2) DEFAULT 0,
  fat DECIMAL(8,2) DEFAULT 0,
  carbs DECIMAL(8,2) DEFAULT 0,
  sodium DECIMAL(10,2) DEFAULT 0,
  sugar DECIMAL(8,2) DEFAULT 0,
  serving_size VARCHAR(40) DEFAULT '100g',
  image TEXT,
  tags JSON
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS sppg;
CREATE TABLE sppg (
  id INT PRIMARY KEY,
  name VARCHAR(255),
  province VARCHAR(120),
  city VARCHAR(120),
  district VARCHAR(120),
  village VARCHAR(120),
  address TEXT,
  status VARCHAR(40),
  source_id VARCHAR(60)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS akg;
CREATE TABLE akg (
  id INT PRIMARY KEY,
  group_name VARCHAR(60),
  gender VARCHAR(10),
  age_range VARCHAR(40),
  calories INT, protein INT, fat INT, carbohydrate INT, fiber INT,
  source_id VARCHAR(60)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS stats;
CREATE TABLE stats (
  id INT PRIMARY KEY AUTO_INCREMENT,
  data JSON NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS simulations;
CREATE TABLE simulations (
  id INT PRIMARY KEY AUTO_INCREMENT,
  name VARCHAR(150) DEFAULT 'Menu Simulasi',
  items JSON NOT NULL,
  total_calories DECIMAL(10,2) DEFAULT 0,
  total_protein DECIMAL(10,2) DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
